package com.mockarena.assessment.api; import com.mockarena.assessment.application.CodingResultApplicationService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/internal/v1/attempts") public class InternalCodingResultController {private final CodingResultApplicationService service;public InternalCodingResultController(CodingResultApplicationService s){service=s;}@PostMapping("/{attemptId}/coding-results")public Response apply(@PathVariable UUID attemptId,@Valid @RequestBody Request r){return service.apply(attemptId,r);}
 public record Request(@NotNull UUID evaluationJobId,@Positive int globalPosition,@NotNull UUID questionId,@NotNull UUID questionVersionId,String sourceFingerprint,@NotBlank String outcome,@NotNull BigDecimal awardedScore,@NotNull BigDecimal maxScore){} public record Response(UUID attemptId,String evaluationStatus){} }
